{
  "key": "bundles",
  "name": {
    "en-US": "Bundles",
    "en-GB": "Bundles",
    "de-DE": "Sets"
  },
  "slug": {
    "en-US": "bundles",
    "en-GB": "bundles",
    "de-DE": "sets"
  },
  "description": {
    "en-US": "Curated bundles — buy the set together.",
    "en-GB": "Curated bundles — buy the set together.",
    "de-DE": "Curated bundles — buy the set together."
  }
}

{
  "key": "bedding-bundle",
  "productType": {
    "typeId": "product-type",
    "key": "bedding-bundle"
  },
  "name": {
    "en-US": "Bedding Bundle",
    "en-GB": "Bedding Bundle",
    "de-DE": "Bedding Bundle"
  },
  "slug": {
    "en-US": "bedding-bundle",
    "en-GB": "bedding-bundle",
    "de-DE": "bedding-bundle"
  },
  "description": {
    "en-US": "Luxe + Lana pillow covers — a curated bedding set.",
    "en-GB": "Luxe + Lana pillow covers — a curated bedding set.",
    "de-DE": "Luxe + Lana pillow covers — a curated bedding set."
  },
  "categories": [
    {
      "typeId": "category",
      "key": "bundles"
    }
  ],
  "taxCategory": {
    "typeId": "tax-category",
    "id": "{{tax_category_id}}"
  },
  "masterVariant": {
    "key": "bedding-bundle-mv",
    "sku": "BEDDING-BUNDLE-01",
    "attributes": [
      {
        "name": "product-ref",
        "value": [
          {
            "typeId": "product",
            "id": "{{luxe_product_id}}"
          },
          {
            "typeId": "product",
            "id": "{{lana_product_id}}"
          }
        ]
      }
    ]
  },
  "publish": true
}

{
  "key": "bundle-line",
  "name": {
    "en-US": "Bundle line link",
    "en-GB": "Bundle line link",
    "de-DE": "Bundle line link"
  },
  "description": {
    "en-US": "Links a bundle's parent line item to its child line items. `bundleId` on the parent; `parentId` on each child pointing at it.",
    "en-GB": "Links a bundle's parent line item to its child line items. `bundleId` on the parent; `parentId` on each child pointing at it.",
    "de-DE": "Links a bundle's parent line item to its child line items. `bundleId` on the parent; `parentId` on each child pointing at it."
  },
  "resourceTypeIds": [
    "line-item"
  ],
  "fieldDefinitions": [
    {
      "name": "bundleId",
      "label": {
        "en-US": "Bundle id (set on the parent line item)",
        "en-GB": "Bundle id (set on the parent line item)",
        "de-DE": "Bundle id (set on the parent line item)"
      },
      "required": false,
      "type": {
        "name": "String"
      },
      "inputHint": "SingleLine"
    },
    {
      "name": "parentId",
      "label": {
        "en-US": "Parent bundle id (set on each child line item)",
        "en-GB": "Parent bundle id (set on each child line item)",
        "de-DE": "Parent bundle id (set on each child line item)"
      },
      "required": false,
      "type": {
        "name": "String"
      },
      "inputHint": "SingleLine"
    }
  ]
}

{
  "key": "bundle-saving",
  "name": {
    "en-US": "Bundle saving — Bedding Bundle",
    "en-GB": "Bundle saving — Bedding Bundle",
    "de-DE": "Bundle saving — Bedding Bundle"
  },
  "description": {
    "en-US": "Books the saving on a bundle's child line items (those carrying custom.parentId). Roll-up stays truthful; the saving is a reportable promotion.",
    "en-GB": "Books the saving on a bundle's child line items (those carrying custom.parentId). Roll-up stays truthful; the saving is a reportable promotion.",
    "de-DE": "Books the saving on a bundle's child line items (those carrying custom.parentId). Roll-up stays truthful; the saving is a reportable promotion."
  },
  "value": {
    "type": "absolute",
    "money": [
      {
        "currencyCode": "EUR",
        "centAmount": 500
      },
      {
        "currencyCode": "USD",
        "centAmount": 600
      },
      {
        "currencyCode": "GBP",
        "centAmount": 400
      }
    ]
  },
  "cartPredicate": "1 = 1",
  "target": {
    "type": "lineItems",
    "predicate": "custom.parentId is defined"
  },
  "sortOrder": "0.87",
  "isActive": true,
  "requiresDiscountCode": false,
  "stackingMode": "Stacking"
}

{
  "key": "save10",
  "name": {
    "en-US": "SAVE10 — 10% off over €100",
    "en-GB": "SAVE10 — 10% off over €100",
    "de-DE": "SAVE10 — 10% off over €100"
  },
  "description": {
    "en-US": "10% off the cart's line items when the total is over €100. Applied by the discount code SAVE10 (task 4.9).",
    "en-GB": "10% off the cart's line items when the total is over €100. Applied by the discount code SAVE10 (task 4.9).",
    "de-DE": "10% off the cart's line items when the total is over €100. Applied by the discount code SAVE10 (task 4.9)."
  },
  "value": {
    "type": "relative",
    "permyriad": 1000
  },
  "cartPredicate": "totalPrice > \"100.00 EUR\"",
  "target": {
    "type": "lineItems",
    "predicate": "1 = 1"
  },
  "sortOrder": "0.55",
  "isActive": true,
  "requiresDiscountCode": true,
  "stackingMode": "Stacking"
}

{
  "code": "SAVE10",
  "name": {
    "en-US": "SAVE10",
    "en-GB": "SAVE10",
    "de-DE": "SAVE10"
  },
  "description": {
    "en-US": "Enter at the cart for 10% off carts over €100.",
    "en-GB": "Enter at the cart for 10% off carts over €100.",
    "de-DE": "Enter at the cart for 10% off carts over €100."
  },
  "cartDiscounts": [
    {
      "typeId": "cart-discount",
      "id": "{{save10_cd_id}}"
    }
  ],
  "isActive": true
}

{
  "key": "monthly",
  "name": {
    "en-US": "Monthly",
    "en-GB": "Monthly",
    "de-DE": "Monthly"
  },
  "description": {
    "en-US": "Deliver every month — the schedule behind Subscribe & Save.",
    "en-GB": "Deliver every month — the schedule behind Subscribe & Save.",
    "de-DE": "Deliver every month — the schedule behind Subscribe & Save."
  },
  "schedule": {
    "type": "standard",
    "value": 1,
    "intervalUnit": "Months"
  }
}

{
  "key": "pickup-store",
  "roles": [
    "InventorySupply"
  ],
  "name": {
    "en-US": "Berlin Pickup Store",
    "en-GB": "Berlin Pickup Store",
    "de-DE": "Berlin Pickup Store"
  },
  "description": {
    "en-US": "A physical pickup location with its own inventory — Buy Online, Pick Up In Store.",
