  }
}

{
  "key": "order-delivered",
  "type": "OrderState",
  "name": {
    "en-US": "Delivered",
    "en-GB": "Delivered",
    "de-DE": "Delivered"
  },
  "description": {
    "en-US": "Handed to the customer — terminal.",
    "en-GB": "Handed to the customer — terminal.",
    "de-DE": "Handed to the customer — terminal."
  },
  "initial": false,
  "transitions": []
}

{
  "key": "order-cancelled",
  "type": "OrderState",
  "name": {
    "en-US": "Cancelled",
    "en-GB": "Cancelled",
    "de-DE": "Cancelled"
  },
  "description": {
    "en-US": "Cancelled before shipping — the authorization is voided (Payment Intents cancelPayment).",
    "en-GB": "Cancelled before shipping — the authorization is voided (Payment Intents cancelPayment).",
    "de-DE": "Cancelled before shipping — the authorization is voided (Payment Intents cancelPayment)."
  },
  "initial": false,
  "transitions": []
}

{
  "key": "order-shipped",
  "type": "OrderState",
  "name": {
    "en-US": "Shipped",
    "en-GB": "Shipped",
    "de-DE": "Shipped"
  },
  "description": {
    "en-US": "Left the warehouse — the payment is CAPTURED at this step.",
    "en-GB": "Left the warehouse — the payment is CAPTURED at this step.",
    "de-DE": "Left the warehouse — the payment is CAPTURED at this step."
  },
  "initial": false,
  "transitions": [
    {
      "typeId": "state",
      "key": "order-delivered"
    }
  ]
}

{
  "key": "order-picked",
  "type": "OrderState",
  "name": {
    "en-US": "Picked",
    "en-GB": "Picked",
    "de-DE": "Picked"
  },
  "description": {
    "en-US": "Picked and packed — orderState Confirmed.",
    "en-GB": "Picked and packed — orderState Confirmed.",
    "de-DE": "Picked and packed — orderState Confirmed."
  },
  "initial": false,
  "transitions": [
    {
      "typeId": "state",
      "key": "order-shipped"
    }
  ]
}

{
  "key": "order-placed",
  "type": "OrderState",
  "name": {
    "en-US": "Placed",
    "en-GB": "Placed",
    "de-DE": "Placed"
  },
  "description": {
    "en-US": "The initial state every new order gets — Checkout created it; nothing has moved yet.",
    "en-GB": "The initial state every new order gets — Checkout created it; nothing has moved yet.",
    "de-DE": "The initial state every new order gets — Checkout created it; nothing has moved yet."
  },
  "initial": true,
  "transitions": [
    {
      "typeId": "state",
      "key": "order-picked"
    },
    {
      "typeId": "state",
      "key": "order-cancelled"
    }
  ]
}

{
  "key": "order-extras",
  "name": {
    "en-US": "Order extras",
    "en-GB": "Order extras",
    "de-DE": "Order extras"
  },
  "description": {
    "en-US": "LHC's custom fields on carts and orders: a gift message, the white-glove flag the cart-rules Extension sets, and the participant who owns the cart.",
    "en-GB": "LHC's custom fields on carts and orders: a gift message, the white-glove flag the cart-rules Extension sets, and the participant who owns the cart.",
    "de-DE": "LHC's custom fields on carts and orders: a gift message, the white-glove flag the cart-rules Extension sets, and the participant who owns the cart."
