    "order"
  ],
  "fieldDefinitions": [
    {
      "name": "giftMessage",
      "label": {
        "en-US": "Gift message",
        "en-GB": "Gift message",
        "de-DE": "Gift message"
      },
      "required": false,
      "type": {
        "name": "String"
      },
      "inputHint": "MultiLine"
    },
    {
      "name": "requiresWhiteGlove",
      "label": {
        "en-US": "Requires white-glove delivery",
