        "de-DE": "Requires white-glove delivery"
      },
      "required": false,
      "type": {
        "name": "Boolean"
      }
    },
    {
      "name": "owner",
      "label": {
        "en-US": "Owner (participant key)",
        "en-GB": "Owner (participant key)",
        "de-DE": "Owner (participant key)"
      },
      "required": false,
      "type": {
        "name": "String"
      },
      "inputHint": "SingleLine"
    }
  ]
}

